using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Windows.Forms;using V15Voice;
public static class Ui141Tests {
 static int count;static object F(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}static object Call(object o,string n,params object[] args){return o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(o,args);}static void Check(bool b,string n){if(!b)throw new Exception("FAIL "+n);Console.WriteLine("PASS "+n);count++;}static IEnumerable<Control> All(Control c){foreach(Control x in c.Controls){yield return x;foreach(var y in All(x))yield return y;}}
 [STAThread]public static void Main(){Application.EnableVisualStyles();var f=new MainForm();int code=0;f.Shown+=(s,e)=>{try{
  Check(f.Text.Contains("1.4.1"),"Window visibly identifies version 1.4.1");var tabs=(TabControl)F(f,"tabs");var device=(ComboBox)F(f,"devicePicker");Check(device.Items.Count==3&&device.SelectedIndex==0,"Device picker offers Auto / NVIDIA GPU / CPU with Auto default");device.SelectedIndex=1;var settings=(VoiceSettings)Call(f,"CaptureSettings");Check(settings.Device=="gpu","Session captures explicit NVIDIA selection");var engine=(KokoroEngine)Call(f,"NewEngine");Check(engine.DeviceMode=="gpu","Studio engine receives the shared GPU preference");var info=(Label)F(f,"batchInfo");Check(info.Text.Contains("NVIDIA GPU"),"Batch visibly uses the same device preference");
  device.SelectedIndex=2;Call(f,"Apply",settings);Check(device.SelectedIndex==1,"Restoring a session restores the GPU mode");Check(All(f).OfType<Button>().Any(x=>x.Text=="Cập nhật từ ZIP")&&All(f).OfType<Button>().Any(x=>x.Text=="Kiểm tra GPU / VRAM"),"Tools expose ZIP update and GPU diagnostics");
  var speed=(NumericUpDown)F(f,"speed");var cap=(NumericUpDown)F(f,"maxSpeed");speed.Value=1.3m;Check(cap.Minimum>=speed.Value&&cap.Value>=speed.Value,"UI never allows a speed cap below the selected base speed");speed.Value=1;cap.Value=1.3m;
  string path=Path.Combine(Path.GetTempPath(),"V15_ui_long_"+Guid.NewGuid().ToString("N")+".srt");var cues=Enumerable.Range(0,3001).Select(i=>new Cue{Id=i+1,Start=i*.2,End=i*.2+.1,Text="Hello."}).ToList();File.WriteAllText(path,Scripts.ToSrt(cues));Call(f,"LoadFile",path);var grid=(DataGridView)F(f,"grid");Check(grid.Rows.Count==3001&&((string)F(f,"sourcePath"))==path,"Studio imports and displays 3001 blocks instead of rejecting over 2000");
  tabs.SelectedIndex=3;var capture=new Timer{Interval=500};capture.Tick+=(x,y)=>{capture.Stop();f.Refresh();using(var bitmap=new System.Drawing.Bitmap(f.Width,f.Height)){using(var g=System.Drawing.Graphics.FromImage(bitmap))g.CopyFromScreen(f.Location,System.Drawing.Point.Empty,f.Size);bitmap.Save(Path.Combine(Path.GetTempPath(),"v15_141_tools.png"));}f.Close();};capture.Start();
  Console.WriteLine("TOTAL UI 1.4.1 "+count+" passed.");
 }catch(Exception ex){Console.WriteLine(ex);code=1;}finally{if(code!=0)f.Close();}};Application.Run(f);Environment.Exit(code);}
}
